import {MIN_K,MAX_K,HUMAN_POWER,createState,tick,snapshot,powerAt,multiplier,yearsAtGrowth} from './model.js';
import {createWorld} from './world.js';
const es=document.documentElement.lang==='es',t=(a,b)=>es?a:b,$=id=>document.getElementById(id),fmt=(v,d=2)=>new Intl.NumberFormat(es?'es-ES':'en-US',{maximumFractionDigits:d}).format(v);
const sci=x=>{const e=Math.floor(Math.log10(x)),m=x/10**e;return fmt(m)+' × 10'+[...String(e)].map(n=>'⁰¹²³⁴⁵⁶⁷⁸⁹'[n]??'⁻').join('');};
const stages=[
 {k:MIN_K,name:t('Referencia humana','Human reference'),scope:t('Un mundo que empieza','A world getting started'),text:t('Usamos 20 TW redondeados como referencia didáctica. Dan K ≈ 0,73. Eso NO significa disponer del 73 % de la potencia del tipo I: aquí es solo un 0,2 %.','We use a rounded 20 TW as a teaching reference. That gives K ≈ 0.73. This does NOT mean having 73% of Type I power: here it is only 0.2%.'),note:t('Referencia elegida, no un dato en tiempo real.','Chosen reference, not a live statistic.')},
 {k:1,name:t('Tipo I · planetaria','Type I · planetary'),scope:t('La escala de un planeta','The scale of a planet'),text:t('El primer umbral de esta convención es 10¹⁶ W. Imagina redes de generación y distribución a escala planetaria. El número no exige una tecnología concreta ni implica controlar el clima.','The first threshold in this convention is 10¹⁶ W. Imagine generation and distribution networks at planetary scale. The number requires no specific technology and does not imply control over the weather.'),note:t('No equivale exactamente a toda la luz que llega a la Tierra.','It is not exactly all sunlight reaching Earth.')},
 {k:2,name:t('Tipo II · estelar','Type II · stellar'),scope:t('Una estrella como referencia','A star as a reference'),text:t('El umbral continuo es 10²⁶ W. Un enjambre de colectores ilustra una posible vía. Nuestro Sol emite unas 3,828 veces esa potencia: el umbral es una normalización, no una estrella exacta.','The continuous threshold is 10²⁶ W. A collector swarm illustrates one possible route. Our Sun emits about 3.828 times that power: the threshold is a normalization, not an exact star.'),note:t('Los colectores del dibujo no son un proyecto de ingeniería.','The depicted collectors are not an engineering plan.')},
 {k:3,name:t('Tipo III · galáctica','Type III · galactic'),scope:t('Muchísimos sistemas estelares','Vast numbers of stellar systems'),text:t('El umbral continuo es 10³⁶ W: unos 2.600 millones de luminosidades solares. La galaxia representa sistemas distribuidos; no una sola máquina ni un control instantáneo de toda la galaxia.','The continuous threshold is 10³⁶ W: about 2.6 billion solar luminosities. The galaxy represents distributed systems, not one machine or instantaneous control of an entire galaxy.'),note:t('Es una clasificación hipotética, no una civilización observada en esta escena.','This is a hypothetical classification, not a civilization observed in this scene.')}
];
let state=createState(),world,speed=1,chartMode='log',last=performance.now(),uiClock=0;
document.title=t('Kardashev — Escalas de civilización','Kardashev — Scales of civilization');
$('app').innerHTML=`<nav class="nav"><a href="../index.html">← Atlas</a><a href="../dyson/index.html">${t('Explorar Dyson','Explore Dyson')} ↗</a><span><a href="${es?'../../kardashev/index.html':'./index.html'}" lang="en">EN</a> / <a href="${es?'./index.html':'../es/kardashev/index.html'}" lang="es">ES</a></span></nav>
<header><span class="eyebrow">NOTEBOOK 07 · ${t('ESCALAS DE CIVILIZACIÓN','SCALES OF CIVILIZATION')}</span><h1>${t('Un planeta. Una estrella.<br>Una galaxia.','A planet. A star.<br>A galaxy.')}</h1><p>${t('Reproduce el salto entre escalas y observa cuánto tiene que crecer la potencia. La distancia entre números pequeños es enorme.','Play the journey between scales and watch how much power must grow. The distance between small numbers is enormous.')}</p></header>
<section class="dashboard"><article><span>${t('Índice Kardashev–Sagan','Kardashev–Sagan index')}</span><strong id="k-value"></strong><small>${t('Escala continua · no es un porcentaje','Continuous scale · not a percentage')}</small></article><article><span>${t('Potencia utilizada','Power used')}</span><strong id="power"></strong><small id="human-multiple"></small></article><article><span>${t('Hasta el siguiente tipo','To the next type')}</span><strong id="gap"></strong><small id="gap-note"></small></article></section>
<div class="transport"><button id="play" class="primary">▶ ${t('Reproducir recorrido','Play journey')}</button><button id="reset" aria-label="${t('Reiniciar','Reset')}">↺</button><label>${t('Velocidad','Speed')} <select id="speed"><option value="1">1×</option><option value="2">2×</option><option value="4">4×</option></select></label><button id="decade">${t('+0,1 K = ×10','+0.1 K = ×10')}</button><span id="play-state"></span></div>
<div class="layout"><section class="stage"><div class="scene-top"><span class="eyebrow" id="view-label"></span><span>${t('MAQUETA 3D · SIN ESCALA DE DISTANCIA','3D MODEL · DISTANCES NOT TO SCALE')}</span></div><div id="space" role="img" tabindex="0" aria-label="${t('Planeta, colectores alrededor de una estrella y galaxia. Arrastra o usa las flechas para girar.','Planet, collectors around a star and galaxy. Drag or use arrow keys to rotate.')}"></div><p id="loading">${t('Preparando las escalas…','Preparing the scales…')}</p><div class="view-controls"><button id="fit">${t('Centrar','Center')}</button><button id="minus" aria-label="${t('Alejar','Zoom out')}">−</button><button id="plus" aria-label="${t('Acercar','Zoom in')}">+</button></div><div class="scene-bottom"><span id="scene-note"></span></div></section><aside><span class="eyebrow">${t('ELIGE UNA ESCALA','CHOOSE A SCALE')}</span><div class="stages">${stages.map((s,i)=>`<button data-stage="${i}"><span>${i===0?t('≈ 0,73','≈ 0.73'):i===1?'I':i===2?'II':'III'}</span><div><b>${s.name}</b><small>${sci(powerAt(s.k))} W</small></div></button>`).join('')}</div><div class="lesson"><h2 id="lesson-title"></h2><p id="lesson-text"></p><small id="lesson-note"></small></div></aside></div>
<section class="scale-control"><label for="scale">${t('Desliza por la escala continua','Slide along the continuous scale')} <output id="scale-output"></output></label><input type="range" id="scale" min="${MIN_K}" max="3" step="any" value="${MIN_K}"><div class="scale-labels"><span>${t('≈ 0,73','≈ 0.73')}</span><span>1</span><span>2</span><span>3</span></div><p>${t('La reproducción recorre magnitudes, no años. Cada +0,1 K multiplica la potencia por 10; cada +1 K, por 10.000.000.000.','Playback travels through magnitudes, not years. Each +0.1 K multiplies power by 10; each +1 K, by 10,000,000,000.')}</p></section>
<section class="comparison"><div><span class="eyebrow">${t('EL SALTO QUE CUESTA IMAGINAR','THE HARD-TO-IMAGINE JUMP')}</span><h2>${t('Diez mil millones de veces.<br>Por cada tipo.','Ten billion times.<br>For every type.')}</h2><p>${t('En una gráfica logarítmica los saltos iguales representan multiplicaciones iguales. Cambia a la escala lineal: los niveles bajos parecen desaparecer junto al tipo III.','On a logarithmic chart, equal jumps represent equal multipliers. Switch to a linear scale: the lower levels seem to disappear beside Type III.')}</p><div class="chart-buttons"><button id="log" aria-pressed="true">${t('Logarítmica','Logarithmic')}</button><button id="linear" aria-pressed="false">${t('Lineal','Linear')}</button></div></div><div><svg id="chart" viewBox="0 0 620 220" role="img"></svg><p class="chart-note" id="chart-note"></p></div></section>
<section class="experiment"><div><span class="eyebrow">${t('EXPERIMENTO MATEMÁTICO','MATHEMATICAL EXPERIMENT')}</span><h2>${t('¿Y si la potencia creciera cada año?','What if power grew every year?')}</h2><p>${t('Mantén una tasa constante e imagina el salto desde el punto seleccionado hasta el siguiente tipo. Es interés compuesto, sin límites de recursos ni construcción.','Hold a growth rate constant and imagine the jump from the selected point to the next type. This is compound growth, without resource or construction limits.')}</p></div><div><label for="growth">${t('Crecimiento anual supuesto','Assumed annual growth')} <output id="growth-label">2 %</output></label><input id="growth" type="range" min="0" max="10" step=".5" value="2"><strong id="years"></strong><small>${t('Resultado condicionado a la tasa · NO es una fecha de llegada','Conditional on the rate · NOT an arrival date')}</small></div></section>
<details class="assumptions"><summary>${t('1964 frente a la escala continua · fuentes y límites','1964 versus the continuous scale · sources and limits')}</summary><p>${t('Kardashev propuso tres tipos. Su tipo I era cercano a la Tierra de su época; II y III se referían a potencias del orden de una estrella y una galaxia (aproximadamente 4×10²⁶ y 4×10³⁷ W). No eran los tres umbrales equidistantes de este control.','Kardashev proposed three types. His Type I was close to Earth in his era; II and III referred to power on the order of a star and a galaxy (approximately 4×10²⁶ and 4×10³⁷ W). They were not the three equally spaced thresholds in this control.')} <a href="https://articles.adsabs.harvard.edu/pdf/1964SvA.....8..217K" target="_blank" rel="noopener">Kardashev, 1964 ↗</a> · <a href="https://doi.org/10.1088/0004-637X/792/1/27" target="_blank" rel="noopener">Wright et al., 2014 ↗</a></p><p>${t('Aquí usamos la convención continua habitual: K = (log₁₀(P en W) − 6) / 10. Así, I = 10¹⁶ W, II = 10²⁶ W y III = 10³⁶ W. El índice mide potencia, no energía acumulada: 1 W = 1 J/s. La referencia humana de 20 TW es redondeada y editable mediante el índice, no una medición de hoy.','Here we use the common continuous convention: K = (log₁₀(P in W) − 6) / 10. Thus I = 10¹⁶ W, II = 10²⁶ W and III = 10³⁶ W. The index measures power, not stored energy: 1 W = 1 J/s. The 20 TW human reference is rounded and can be explored using the index; it is not a measurement for today.')} <a href="https://doi.org/10.1038/s41598-023-38351-y" target="_blank" rel="noopener">${t('Fórmula y contexto: Zhang et al., 2023','Formula and context: Zhang et al., 2023')} ↗</a></p><p>${t('Las luces y colectores ilustran el cambio de ámbito; su cantidad no representa una fracción física de energía. La luminosidad solar nominal usada para comparar es 3,828×10²⁶ W. Los niveles IV y V no pertenecen a la clasificación original y quedan fuera de esta simulación. La escala no mide bienestar, justicia, inteligencia ni eficiencia. Ninguna tasa de crecimiento garantiza alcanzar otro tipo.','Lights and collectors illustrate the change in scope; their count does not represent a physical energy fraction. The nominal solar luminosity used for comparison is 3.828×10²⁶ W. Types IV and V are not part of the original classification and are outside this simulation. The scale does not measure well-being, justice, intelligence or efficiency. No growth rate guarantees reaching another type.')}</p></details>
<footer>Atlas · Kardashev · <a href="../dyson/index.html">${t('Siguiente exploración: construir un enjambre de Dyson','Next exploration: building a Dyson swarm')} ↗</a></footer>`;
try{world=createWorld($('space'));$('loading').hidden=true;}catch(e){$('loading').textContent=t('La vista 3D no está disponible. Los controles, cifras y gráficas siguen funcionando.','The 3D view is unavailable. Controls, figures and charts still work.');console.error(e);}
function chart(v){const left=64,right=600,top=16,bottom=182,x=k=>left+(k-MIN_K)/(MAX_K-MIN_K)*(right-left),y=p=>bottom-(chartMode==='log'?(Math.log10(p)-Math.log10(HUMAN_POWER))/(36-Math.log10(HUMAN_POWER)):p/1e36)*(bottom-top);let svg='';for(const exponent of [16,26,36]){const yy=y(10**exponent);if(chartMode==='linear'&&exponent<36)continue;svg+=`<path d="M${left} ${yy}H${right}" stroke="#324056"/><text x="2" y="${yy+4}" fill="#a6b7cd" font-size="11">10<tspan baseline-shift="super" font-size="8">${exponent}</tspan> W</text>`;}const pts=Array.from({length:161},(_,i)=>{const k=MIN_K+(MAX_K-MIN_K)*i/160;return `${x(k)},${y(powerAt(k))}`;}).join(' ');svg+=`<polyline points="${pts}" fill="none" stroke="#afa6e7" stroke-width="2.5"/><circle cx="${x(v.k)}" cy="${y(v.power)}" r="5" fill="#ffce96"/>`;for(const s of stages)svg+=`<text x="${x(s.k)}" y="211" fill="#a6b7cd" text-anchor="middle" font-size="11">K ${fmt(s.k)}</text>`;$('chart').innerHTML=svg;$('chart').setAttribute('aria-label',t('Potencia frente a índice K. Punto seleccionado: ','Power versus K index. Selected point: ')+sci(v.power)+' W');$('chart-note').textContent=chartMode==='log'?t('Altura: log₁₀ de la potencia. La recta oculta un crecimiento multiplicativo.','Height: log₁₀ of power. The straight line encodes multiplicative growth.'):t('Altura: potencia en W. Tipo II es una diez mil millonésima parte del tipo III.','Height: power in W. Type II is one ten-billionth of Type III.');}
function paint(){const v=snapshot(state),stage=v.k<1?0:v.k<2?1:v.k<3?2:3;const lesson=stages[stage];$('k-value').textContent='K '+fmt(v.k,3);$('power').textContent=sci(v.power)+' W';$('human-multiple').textContent='× '+(v.vsHuman<1e6?fmt(v.vsHuman):sci(v.vsHuman))+' '+t('la referencia humana','the human reference');$('gap').textContent=v.k>=3?t('Tipo III alcanzado','Type III reached'):(v.remainingFactor<=1e10?fmt(v.remainingFactor):sci(v.remainingFactor))+'×';$('gap-note').textContent=v.k>=3?t('Fin del recorrido ilustrativo','End of the illustrative journey'):t('Potencia necesaria para el tipo ','Power needed for Type ')+['','I','II','III'][v.next];$('scale').value=v.k;$('scale-output').textContent='K '+fmt(v.k,3);$('play').textContent=state.playing?'Ⅱ '+t('Pausar','Pause'):v.k>=3?'↺ '+t('Repetir','Replay'):'▶ '+t('Reproducir recorrido','Play journey');$('play-state').textContent=state.playing?t('Recorriendo magnitudes','Exploring magnitudes'):t('En pausa','Paused');$('decade').disabled=v.k>=3;$('view-label').textContent={planet:t('ESCALA PLANETARIA','PLANETARY SCALE'),star:t('ESCALA ESTELAR','STELLAR SCALE'),galaxy:t('ESCALA GALÁCTICA','GALACTIC SCALE')}[v.view];$('scene-note').textContent=t('Luces y colectores esquemáticos · arrastra para girar','Schematic lights and collectors · drag to rotate');$('lesson-title').textContent=lesson.scope;$('lesson-text').textContent=lesson.text;$('lesson-note').textContent=lesson.note;document.querySelectorAll('[data-stage]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===stage)));const rate=+$('growth').value,years=yearsAtGrowth(v.k,v.next,rate);$('growth-label').textContent=fmt(rate)+' %';$('years').textContent=!Number.isFinite(years)?t('Sin crecimiento, no se alcanza','No growth, no arrival'):years===0?t('Umbral alcanzado','Threshold reached'):fmt(years,0)+' '+t('años hipotéticos','hypothetical years');chart(v);world?.render(state,v);}
function setK(k){state.k=Math.max(MIN_K,Math.min(MAX_K,k));state.playing=false;paint();}
$('play').onclick=()=>{if(state.k>=MAX_K)state=createState();state.playing=!state.playing;last=performance.now();paint();};$('reset').onclick=()=>{state=createState();world?.fit();paint();};$('scale').oninput=e=>setK(+e.target.value);$('decade').onclick=()=>setK(state.k+.1);$('speed').onchange=e=>speed=+e.target.value;document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>setK(stages[+b.dataset.stage].k));$('growth').oninput=paint;for(const mode of ['log','linear'])$(mode).onclick=()=>{chartMode=mode;$('log').setAttribute('aria-pressed',String(mode==='log'));$('linear').setAttribute('aria-pressed',String(mode==='linear'));paint();};$('fit').onclick=()=>world?.fit();$('plus').onclick=()=>world?.zoomBy(1.15);$('minus').onclick=()=>world?.zoomBy(1/1.15);document.addEventListener('visibilitychange',()=>last=performance.now());paint();
function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(!document.hidden){const wasPlaying=state.playing;tick(state,dt*speed);world?.render(state,snapshot(state));uiClock+=dt;if(wasPlaying&&uiClock>.08){paint();uiClock=0;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
